package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string          // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsOverflows int64 = 0                               // PIC 99 len=2 = 0
var WsCount int64 = 0                                   // PIC 99 len=2 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V9 len=6 = 0
var WsAmtEd string  // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string // PIC ZZ,ZZ9.9 len=8

var amtFile *os.File
var amtScanner *bufio.Scanner
var curRec AmtRec
var eofReached bool

func intPow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storeNumeric(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	truncated := val.Truncate(int32(scale))
	mod := intPow10(intDigits + scale)
	// scaled integer
	scaledDec := truncated.Shift(int32(scale)).Truncate(0)
	intVal := scaledDec.IntPart()
	wrapped := intVal % mod
	if wrapped < 0 {
		wrapped += mod
		// for negative numbers with more than one wrap, ensure positive
		wrapped %= mod
	}
	return decimal.New(wrapped, int32(-scale))
}

func isOverflow(val decimal.Decimal, intDigits int) bool {
	// overflow if val >= 10^intDigits  (positive values)
	threshold := decimal.NewFromInt(intPow10(intDigits))
	return val.Cmp(threshold) >= 0
}

func formatEdited(val decimal.Decimal, pic string) string {
	// Determine decimal places from picture
	dotIdx := strings.Index(pic, ".")
	intPic := pic
	decPlaces := 0
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPlaces = len(pic) - dotIdx - 1
	}
	// count integer slots (Z or 9)
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	// Ensure val is truncated to decPlaces (should already be)
	v := val.Truncate(int32(decPlaces))
	// Handle high order drop for edited field as per spec
	// Drop high digits if integer part too large
	// This is equivalent to wrapping integer part modulo 10^intSlots
	// But val coming from limited fields already fits, however implement
	// for completeness (use storeNumeric logic for integer part)
	// We apply wrapping on the whole value to drop high digits:
	// Reuse storeNumeric to enforce size, then format.
	// However storeNumeric already applied on source fields; for safety:
	// If integer part digits > intSlots, keep low-order.
	// Implement by integer part modulo.
	if intSlots > 0 {
		// check integer digits count
		intPart := v.Truncate(0).Abs()
		// count digits of intPart
		ipStr := intPart.StringFixed(0) // without sign
		// StringFixed may produce without leading zeros, but for large values
		// if len > intSlots, we need to keep low-order digits
		if len(ipStr) > intSlots {
			// keep low-order intSlots digits
			ipStr = ipStr[len(ipStr)-intSlots:]
			// reconstruct value with same fractional part
			frac := v.Sub(v.Truncate(0))
			// frac may be negative? not here
			ipDec, _ := decimal.NewFromString(ipStr)
			if v.Sign() < 0 {
				ipDec = ipDec.Neg()
				// frac is negative already
			}
			v = ipDec.Add(frac)
		}
	}

	// Build integer padded string
	intPartDec := v.Truncate(0).Abs()
	intPartStr := intPartDec.StringFixed(0)
	// intPartStr is e.g. "0" for zero
	if intPartStr == "" {
		intPartStr = "0"
	}
	// pad to intSlots with leading zeros
	if len(intPartStr) < intSlots {
		intPartStr = strings.Repeat("0", intSlots-len(intPartStr)) + intPartStr
	} else if len(intPartStr) > intSlots {
		// already handled dropping, but just keep rightmost
		intPartStr = intPartStr[len(intPartStr)-intSlots:]
	}
	// fractional part
	fracStr := ""
	if decPlaces > 0 {
		// get fractional digits
		// v has scale decPlaces, we can format
		// Use StringFixed to get decPlaces
		fixed := v.Abs().StringFixed(int32(decPlaces))
		// fixed like "1234.56"
		parts := strings.SplitN(fixed, ".", 2)
		if len(parts) == 2 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", decPlaces)
		}
		// ensure length
		if len(fracStr) < decPlaces {
			fracStr = fracStr + strings.Repeat("0", decPlaces-len(fracStr))
		}
	}

	// Map digits to picture
	out := []rune(pic)
	// We need to fill Z/9 positions with digits from intPartStr
	idx := 0
	for i, ch := range pic {
		if ch == 'Z' || ch == '9' {
			if dotIdx >= 0 && i > dotIdx {
				// decimal part
				// there are decPlaces positions after dot, all are '9'
				decIdx := 0
				// count how many Z/9 before this position after dot
				// Simpler: fill decimal digits sequentially
				// Determine position among decimal digits
				// Count Z/9 after dot up to i
				cnt := 0
				for k := dotIdx + 1; k <= i; k++ {
					if pic[k] == 'Z' || pic[k] == '9' {
						cnt++
					}
				}
				decIdx = cnt - 1
				if decIdx >= 0 && decIdx < len(fracStr) {
					out[i] = rune(fracStr[decIdx])
				} else {
					out[i] = '0'
				}
			} else {
				// integer part
				if idx < len(intPartStr) {
					out[i] = rune(intPartStr[idx])
					idx++
				} else {
					out[i] = '0'
				}
			}
		} else if ch == '.' || ch == ',' {
			// keep as is (will be possibly replaced if comma suppressed)
			out[i] = ch
		}
	}

	// Z suppression
	suppressing := true
	for i, ch := range pic {
		if ch == 'Z' {
			if suppressing {
				if out[i] == '0' {
					out[i] = ' '
				} else {
					suppressing = false
				}
			} else {
				// keep digit
			}
		} else if ch == '9' {
			// 9 never suppressed, and ends suppression
			suppressing = false
		} else if ch == ',' {
			if suppressing {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if ch == '.' {
			// decimal point always kept
			// but if still suppressing (integer part all zero) we have already
			// handled commas; dot stays
			suppressing = false
		}
	}
	return string(out)
}

func inputDone() bool {
	return WsEofFlag == "Y"
}

func ReadPara() {
	if eofReached {
		WsEofFlag = "Y"
		return
	}
	if !amtScanner.Scan() {
		WsEofFlag = "Y"
		eofReached = true
		return
	}
	line := amtScanner.Text()
	// Remove possible \r (already stripped by Scanner, but be safe)
	line = strings.TrimSuffix(line, "\r")
	// Pad with spaces on right to 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	arAcct := line[0:4]
	arAmtRaw := line[4:11]
	// parse arAmtRaw: digits only, implied V99
	trimmed := strings.TrimSpace(arAmtRaw)
	// If trimmed contains spaces inside, remove? Assume digits only
	// If empty => 0
	var amt decimal.Decimal
	if strings.TrimSpace(arAmtRaw) == "" {
		amt = decimal.NewFromInt(0)
	} else {
		// Remove non-digit (spaces) -> treat as 0? but spec says digits only
		digits := ""
		for _, c := range arAmtRaw {
			if c >= '0' && c <= '9' {
				digits += string(c)
			} else if c == ' ' {
				// space inside numeric -> treat as 0? COBOL would treat as 0
				// For padded short line, spaces are trailing, already handled as missing digits =0
				// We'll interpret spaces as '0' for numeric? But spec says pad spaces on right,
				// for numeric field that would be spaces -> COBOL may treat as 0?
				// We'll treat space as '0' if we are padding? Simpler treat as '0'
				digits += "0"
			}
		}
		if digits == "" {
			digits = "0"
		}
		// digits length should be 7, but if shorter due to original shorter line we padded with zeros above
		// Parse as integer
		n, _ := decimal.NewFromString(digits)
		// implicit 2 decimals
		amt = decimal.New(n.IntPart(), -2)
		_ = trimmed
	}
	curRec.ArAcct = arAcct
	curRec.ArAmt = amt
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	sumBig := WsBigTotal.Add(curRec.ArAmt)
	WsBigTotal = storeNumeric(sumBig, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeNumeric(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	sumSafe := WsSafeTotal.Add(curRec.ArAmt)
	if isOverflow(sumSafe, 5) {
		OverflowPara()
	} else {
		WsSafeTotal = storeNumeric(sumSafe, 5, 2)
	}

	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100

	// COMPUTE WS-HALF = AR-AMT / 2  (truncated)
	halfRaw := curRec.ArAmt.Div(decimal.NewFromInt(2))
	WsHalf = storeNumeric(halfRaw, 5, 1)

	// MOVEs to edited
	WsAmtEd = formatEdited(curRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	// DISPLAY
	// AR-ACCT is exactly 4 chars, including trailing spaces
	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	PerformReadPara()
}

func PerformReadPara() { ReadPara() }

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func MainPara() {
	// OPEN INPUT AMT-FILE
	var err error
	amtFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer amtFile.Close()
	amtScanner = bufio.NewScanner(amtFile)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	amtScanner.Buffer(buf, 1024*1024)
	eofReached = false

	PerformReadPara()
	for !inputDone() {
		ProcessPara()
	}
	// CLOSE AMT-FILE (deferred)
	SummaryPara()
}

func main() {
	MainPara()
}
